const cfg=JSON.parse($vars.TMX_TASK_CONFIG_JSON || '{}');
const base=String($vars.TMX_TASK_API_BASE || '');
if(!base.startsWith('https://') || !base.slice(8) || /[^a-z0-9.:-]/i.test(base.slice(8))) throw new Error('Use HTTPS na API TMX');
return ($input.first().json.commands || []).map(command=>{
 const task=command.task, settings=cfg[task.sector];
 if(!settings || !/^\d+$/.test(settings.listId) || !/^\d+$/.test(settings.channelId)) throw new Error('Setor sem lista/canal configurados: '+task.sector);
 const desired=command.action==='create'?'pending':command.status;
 if(!settings.statuses?.[desired]) throw new Error('Status da lista não mapeado');
 if(command.action==='status' && (!task.clickupId || !task.discordMessageId || !task.discordChannelId)) throw new Error('Vincule a mensagem Discord antes de alterar');
 const ids=task.assignees.map(p=>Number(p.clickupId));
 if(ids.some(id=>!Number.isSafeInteger(id)||id<=0)) throw new Error('Responsável ClickUp inválido');
 return {json:{command,settings,desired,method:command.action==='create'?'POST':'PUT',
 url:command.action==='create'?'https://api.clickup.com/api/v2/list/'+settings.listId+'/task':'https://api.clickup.com/api/v2/task/'+encodeURIComponent(task.clickupId),
 body:command.action==='create'?{name:task.title,markdown_description:'Oferta: '+(task.offer||'Sem oferta')+'\nSetor: '+task.sector+'\n\n'+task.description+'\n\nOrigem: TMX request '+command.id,
 assignees:ids,status:settings.statuses[desired],priority:({urgent:1,high:2,normal:3,low:4})[task.priority],...(task.dueAt?{due_date:Date.parse(task.dueAt),due_date_time:true}:{})}:{status:settings.statuses[desired]}}};
});

const input=$('Preparar comandos').item.json;
const remote=$input.item.json;
if(!remote.id || !/^[a-zA-Z0-9_-]+$/.test(String(remote.id))) throw new Error('ClickUp não confirmou taskId');
if(input.command.action==='status' && String(remote.id)!==input.command.task.clickupId) throw new Error('ClickUp não confirmou a identidade da tarefa');
if(remote.status?.status!==input.settings.statuses[input.desired]) throw new Error('ClickUp não confirmou o status solicitado');
const actual=(remote.assignees||[]).map(p=>String(p.id));
const expected=input.command.task.assignees.map(p=>p.clickupId);
if(actual.length!==expected.length || expected.some(id=>!actual.includes(id))) throw new Error('ClickUp não confirmou todos os responsáveis');
const iso=v=>v && Number.isFinite(Number(v)) ? new Date(Number(v)).toISOString():null;
const at=iso(remote.date_updated);
if(!at) throw new Error('ClickUp não retornou data de atualização');
const task={...input.command.task,clickupId:String(remote.id),status:input.desired,
 updatedAt:at,completedAt:input.desired==='done'?iso(remote.date_done || remote.date_closed):null,
 startedAt:input.desired==='progress'&&input.command.task.status!=='progress'?(input.command.task.startedAt||at):input.command.task.startedAt,assignedAt:input.command.task.assignedAt,
 syncState:'synced',discordState:'pending'};
return {json:{...input,task,event:{eventId:input.command.id+':clickup',task}}};
